      "subgoal": "Explain visible light tracking and fiducial tracking using artificial landmarks."
    },
    {
      "start": 110,
      "subgoal": "Describe natural feature tracking using feature detection, descriptors, and pose matching."
    },
    {
      "start": 125,
      "subgoal": "Explain model-based tracking using SLAM and PTAM."
    },
    {
      "start": 140,
      "subgoal": "Describe 3D structure tracking using depth sensors and created 3D models."
    },
    {
      "start": 153,
      "subgoal": "Explain inertial tracking and additional positional sensors such as GPS, including RTK and limitations."
    },
    {
      "start": 173,
      "subgoal": "Describe motion capture, eye tracking, and hybrid tracking methods."
    },
    {
      "start": 192,
